def is_schedulability_sustainable_wrt_blocking_vector_decrease(schedulability_test, taskset, priority_ordering):
    for task_k in taskset:
        # Assume task_k is schedulable with current FNRs
        if not is_schedulable(task_k, taskset, priority_ordering, schedulability_test):
            continue

        original_FNRs = {task.id: task.FNR_length for task in taskset}

        # Reduce FNR of a lower priority task
        for task_lp in get_tasks_with_lower_priority(taskset, task_k, priority_ordering):
            if task_lp.FNR_length > 0:
                task_lp.FNR_length -= 1

                # Check if task_k is still schedulable
                if not is_schedulable(task_k, taskset, priority_ordering, schedulability_test):
                    # Restore FNRs and return False
                    for task_id, fnr_len in original_FNRs.items():
                        taskset[task_id].FNR_length = fnr_len
                    return False

                # Restore FNR for next iteration
                task_lp.FNR_length += 1
